from pathlib import Path
from PIL import Image
import json,hashlib
p=Path(__file__).resolve().parent;r=p.parents[1];out=p/'shoulder-donor-v33';out.mkdir(exist_ok=True)
base=p/'leg-bridge-v20/candidate.png';donor=r/'character/james-cargo-return-bridges-v1/frames-v9/bare/000.png'
walk=p/'master-head-review-v16/bare-000.png';standing=r/'character/james-carry-headcaps-v1/frames/004.png'
refs=[]
for f,label in [(base,'target'),(donor,'actual-pose-guide'),(walk,'following-walk-pose'),(standing,'case-master')]:
    dst=out/(label+'.png');im=Image.open(f).convert('RGBA');assert im.size==(256,256);im.resize((1024,1024),Image.Resampling.LANCZOS).save(dst);refs.append(dst)
prompt='''Use case: precise-object-edit. Edit Image1 James carrying sprite. Replace its upper-body stance with the actual narrow profile carrying anatomy shown in Image2: shoulder, collar below the neck, chest, elbow, forearm and waist connection. Image2 is an existing real transition source, not a color or equipment reference. Image3 is the immediately following walking pose. The retained near/far legs in Image1 already prepare that gait; leave those legs unchanged. Use the upper shoulder/chest profile from Image2, so the near elbow sits close to his ribcage and the torso is directly above his narrowed hips. This is a visible anatomical pose change, not a minor texture edit or a case translation.
Image1/Image4 own all identity, matte material and the compact graphite case design: four small dull-silver corner latches, original panel proportions, two gloved hands holding its edges. Keep the case at Image1 existing waist position and physical size; do not push it forward, inflate it, lower it, or let hands float or clip the stomach. Keep head, face, hair, goggles and neck above the collar identical to Image1. The collar and shoulder seam below his neck MUST follow the new torso anatomy; they are allowed to change. Keep Image1 leg stance/knees/shins/boots, sole position, standing height and framing. Holstered meter and wrench remain on belt; no wrench in his hands, no added devices. Match Image1/Image4 muted neutral charcoal fabric, softly shaded matte detail, subdued mustard markings and soft metal highlights exactly; no purple, no gloss, no brighter whites, no chunky black outlines or simplification into flat cartoon shapes. No shadow added behind the arm or backpack. All images are identical256x256 native canvases enlarged4x. Return the same square image with genuine transparency, same head/feet placement and body scale. One sprite, no sheet/text/ground shadow.'''
pf=out/'prompt.txt';pf.write_text(prompt+'\n',encoding='utf-8')
files=[base,donor,walk,standing,Path(__file__),pf]+refs
(out/'inputs.json').write_text(json.dumps(dict(baseFile=base.relative_to(r).as_posix(),donorSource=donor.relative_to(r).as_posix(),crop=[0,0,256,256],admissionRegion=[88,104,166,169],protectedFaceAboveY=104,changedProtection='Collar/shoulder rows104..109 deliberately released; previous entire fixed head/collar rectangle is not an invariant for this candidate. Face above104 and source legs outside admission remain exact.',references=[f.relative_to(r).as_posix() for f in refs],preCallSha256={f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in files}),indent=2)+'\n')
print('V33 full-body pose guide prepared; face protected, collar/shoulder authoring permitted.')
